import React from 'react';
import 'jquery.terminal';
import 'jquery.terminal/css/jquery.terminal.css';
import './Terminal.css';
import $ from 'jquery';
import * as R from 'ramda';

window.R = R;
window.$ = $;

window.greetings = `--- Hybrid UI - Alex Varga ---

Type 'help' and press enter for help.
Type 'hui' and press enter for info about Hybrid UIs.
Type 'about' and press enter for info about this demo.

NOTE: Currently using my WIP layout algorithm for term trees.
      Try 'setLay(dagre)' or 'setLay(klay)'.
`;
window.help = `
This console runs ordinary Javascript.
Click on something on the left to send an identifier like 'G(_)' to the console.

- Basic JS:
  => x = 2+2
  => x*x
- Add an node/edge/both:
  => add()
  => add(G(_), G(_))
  => add(G(_), add())
- Remove nodes/edges:
  => rem(G(_), ...)
- Split an edge:
  => spl(G(_))
`;
window.hui = `
In a hybrid UI, all actions happen through the console, and the GUI only displays information and sends command fragments to the console.
It makes for unideal interfaces, but allows for:
- Rapid prototyping of interface functionality
- Reproducibility of interaction
`;
window.about = `
This demo was built using:
- React
- react-cytoscape
- jquery.terminal
`;

function toString(x) {
  if (typeof x === 'string') {
    return `[[;gold;]"${ x }"]`;
  } else if (!isNaN(x)) {
    return `[[;mediumorchid;]${ String(x) }]`;
  } else if (Array.isArray(x)) {
    if (x.length > 10) {
      return "[[;limegreen;]⁅]" + x.slice(0, 10).map(toString).join("[[;limegreen;], ]") + "[[;limegreen;], ]...[[;limegreen;]⁆]"
    } else {
      return "[[;limegreen;]⁅]" + x.map(toString).join("[[;limegreen;], ]") + "[[;limegreen;]⁆]";
    }
  } else if (typeof x === 'object') {
    return "[[;orange;]{]...[[;orange;]}]";
  } else if (typeof x === "function") {
    return `[[;royalblue;](${ x.name })]`;
  } else {
    return String(x);
  }
}

class Terminal extends React.Component {
  constructor(props) {
    super(props);
    this.state = {command: ''};
  }
  update(command) {
    this.setState({
      command
    });
  }
  componentDidMount() {
    var {interpreter, ...options} = this.props;
    if (!options.onCommandChange) {
      options.onCommandChange = (command) => this.update(command);
    }
    interpreter = interpreter || function(command, term) {
      if (command !== '') {
        try {
          var result = window.eval(command);
          if (result !== undefined) {
            term.echo(toString(result));
          }
        } catch(e) {
          term.error(String(e));
        }
      } else {
        term.echo('');
      }
    };
    this.terminal = $(this.node).terminal(interpreter, options);
  }
  componentWillUnmount() {
    this.terminal.destroy();
  }
  isCommandControlled() {
    return this.props.command !== undefined;
  }
  render() {
    return (
      <div ref={(node) => this.node = node}></div>
    );
  }
}

export default Terminal;



