import React from 'react';
import './App.css';
import Terminal from './Terminal';
import Cytoscape from './Cytoscape.js';
import {Row, Col} from 'react-bootstrap';
import FontAwesome from 'react-fontawesome';

class App extends React.Component {
  constructor(props) {
    super(props);
    this.send = this.send.bind(this);
    this.setupTerm = this.setupTerm.bind(this);
  }
  send(val) {
    this.term.insert(val);
  }
  setupTerm(term) {
    window.term = this.term = term;

    term.focus();
    document.addEventListener('click', () => setTimeout(term.focus, 0));
  }
  render() {
    return (
      <div className="App">
        <Row>
          <Col xs={6} sm={6} md={7} lg={7} style={{"background": "linear-gradient(to bottom right, palegreen, aqua)"}}>
            <div className="App-body">
              <p className="App-logo" onClick={()=>this.send("secret()")}>
                <FontAwesome
                  name='mouse-pointer'
                  style={{ transform: 'scale(0.6, 1) rotate(112.5deg)' }} />
                _
              </p>
              <Cytoscape send={this.send} />
            </div>
          </Col>
          <Col xs={6} sm={6} md={5} lg={5}>
            <Terminal
              onInit={this.setupTerm}
              greetings={window.greetings}
              prompt="=> " />
          </Col>
        </Row>
      </div>
    );
  }
}

window.secret = function() {
  setTimeout(function() {
    var win = window.open("https://youtu.be/ZZ5LpwO-An4", '_blank');
    win.focus();
  }, 1000);
  return "What's going on?";
}

export default App;



